command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: SCHWARZE KATZE (Ausführung)
// ==========================================

(async () => {
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Schwarze Katze";
    const ahne = "Aphasma"; 
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    let whisperIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => whisperIds.add(id));

    let targets = Array.from(game.user.targets);
    if (targets.length === 0 || targets.length > 1) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle genau EIN Ziel (Target) aus!");
    }
    const targetActor = targets[0].actor;
    if (!targetActor) return;

    getOwners(targetActor).forEach(id => whisperIds.add(id));

    // --- ZIEL-PRÜFUNGEN (Lebewesen & Schips) ---
    const zielSpezies = (targetActor.system?.details?.species?.value || targetActor.system?.details?.species || targetActor.system?.species?.value || "").toLowerCase();

    const isGeist = DSK_FW.Effekt.CheckTarget(targetActor, "geist") || zielSpezies.includes("geist");
    const isUntot = zielSpezies.includes("untot") || zielSpezies.includes("skelett") || zielSpezies.includes("zombie");
    const isVampir = zielSpezies.includes("vampir");
    const isDaemon = zielSpezies.includes("dämon") || zielSpezies.includes("daemon");
    const isElementar = zielSpezies.includes("elementar");
    const isGolem = zielSpezies.includes("golem") || zielSpezies.includes("homunkulus");

    const isLebewesen = !(isGeist || isUntot || isVampir || isDaemon || isElementar || isGolem);
    const targetSchips = foundry.utils.getProperty(targetActor, "system.stats.schips.value") || 0;

    if (!isLebewesen || targetSchips <= 0) {
        let fehlerGrund = !isLebewesen ? "Das Ziel ist kein Lebewesen." : "Das Ziel besitzt keine Schicksalspunkte.";
        const failContent = `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="margin-bottom: 8px; text-align: left;"><b>${casterActor.name}</b> versucht <b>${targetActor.name}</b> mit Pech zu verfluchen...</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="text-align:center; color:#B30000; font-weight:bold; font-size: 1.1em;">Fehlschlag!</p>
                    <p style="text-align:center; font-size: 0.9em; margin-bottom: 0;">${fehlerGrund}</p>
                </div>
            </div>
        `;
        let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
        if (msg) { await msg.update({ content: failContent, whisper: Array.from(whisperIds) }); } 
        else { await ChatMessage.create({ speaker: { alias: "System" }, whisper: Array.from(whisperIds).filter(id => game.users.get(id)), content: failContent }); }
        await casterActor.unsetFlag("world", "letzteGabenQS");
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
        return; 
    }

    // --- BERECHNUNGEN (QS/2 kaufmännisch runden) ---
    const schipVerlust = Math.ceil(qs / 2);
    let tatsaechlicherVerlust = schipVerlust;
    let schipHinweis = "";

    // Prüfung und dynamischer Hinweis mit vorheriger Trennlinie
    if (targetSchips < schipVerlust) {
        tatsaechlicherVerlust = targetSchips;
        let wortEinzahl = tatsaechlicherVerlust === 1 ? "konnte nur einer" : `konnten nur ${tatsaechlicherVerlust}`;
        let punktEinzahl = targetSchips === 1 ? "Schicksalspunkt" : "Schicksalspunkte";
        schipHinweis = `
            <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
            <p style="margin-top: 8px; margin-bottom: 8px; font-size: 0.9em; color: #76301b; text-align: left;">
                <b>Hinweis:</b> ${targetActor.name} hatte leider nur ${targetSchips} ${punktEinzahl}. Ihm sollten ${schipVerlust} von Aphasma abgezogen werden, doch es ${wortEinzahl} gestrichen werden.
            </p>
        `;
    }

    // --- EFFEKT ANWENDEN ---
    let alterEffekt = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    await targetActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        description: `Das Pech klebt an den Pfoten dieses Lebewesens. Es hat ${tatsaechlicherVerlust} Schicksalspunkte verloren. Dieser Fluch hält bis zur nächsten Toten Mada an.`,
        changes: [{
            key: "system.stats.schips.gearmodifier",
            mode: 2, 
            value: `-${tatsaechlicherVerlust}`,
            priority: 20
        }],
        flags: { core: { statusId: "downgrade" } }
    }]);

    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    // --- CHAT-KARTE BAUEN ---
    const cardContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px; text-align: left;"><b>${casterActor.name}</b> bringt <b>${targetActor.name}</b> schreckliches Pech!</p>
                <p style="margin-top:0; margin-bottom: 8px; text-align: left;">Das Schicksal wendet sich von dem anvisierten Lebewesen ab.</p>

                <ul class="dsklist" style="margin-bottom: 8px; text-align: left;">
                    <li><b>Verlust von Schicksalspunkten:</b> <b>-${tatsaechlicherVerlust} Schips</b></li>
                    <li><b>Zielkategorie:</b> Lebewesen</li>
                    <li><b>Reichweite:</b> 4 Schritt</li>
                </ul>

                ${schipHinweis}

                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold; margin-bottom: 4px;">
                    Wirkungsdauer:<br>Bis zur nächsten Toten Mada
                </p>
                <p style="text-align:center; margin-bottom: 0;">
                    <span style="font-size: 0.9em; font-weight: 300; opacity: 0.8;">(Berechnung: QS ${qs} / 2 = ${schipVerlust})</span>
                </p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: cardContent, whisper: Array.from(whisperIds) });
    } else {
        await ChatMessage.create({
            speaker: { alias: "System" },
            whisper: Array.from(whisperIds).filter(id => game.users.get(id)),
            content: cardContent
        });
    }
})();
